      'รอประมาณ 30 วินาที แล้วดูแถบเหนือตาราง และคอลัมน์ "Script Approve" ของสมาชิกที่ไม่ใช่ Owner (ชี้เมาส์ที่ช่องนั้นค้างไว้)',
