      'WS ที่ใช้ครบ 100%: แถบสีแดง "โควต้า ชั่วโมงอวาตาร์ เต็มแล้ว — เริ่มงานใหม่ไม่ได้จนกว่าจะขึ้นรอบใหม่หรืออัปเกรดแพ็กเกจ" (ถ้าเต็มหลายตัวจะคั่นชื่อด้วย " · ")',
      'แถว "ชั่วโมงอวาตาร์" แสดงค่าที่ใช้ไป / โควตา ชม. ตรงกับระดับที่เตรียม และแถบความคืบหน้าเต็มตามสัดส่วน',
