     data=['แถว 1: WS ที่ใช้ชั่วโมงอวาตาร์ไปประมาณ 85% ของโควตารอบนี้', 'แถว 2: WS ที่ใช้ชั่วโมงอวาตาร์ครบ 100% ของโควตารอบนี้'],
