   pre=['ล็อกอินเป็น Owner', 'มีเสียงทดสอบใน "เสียงของฉัน" ที่ไม่ได้ใช้ในไลฟ์ที่ยังไม่จบ (ลบทิ้งได้)', 'มีบัญชีสมาชิกที่ไม่ใช่ Owner ใน workspace เดียวกันสำหรับตรวจข้อสุดท้าย'],
