   pre=['ล็อกอินเป็น Owner', 'มีเสียงทดสอบใน "เสียงของฉัน" สถานะ "พร้อมใช้"', 'มีไลฟ์ที่ตั้งเวลาไว้และยังไม่จบ 1 ไลฟ์ ที่ฉากในไลฟ์เลือกใช้เสียงทดสอบนี้ (เลือกในหน้าต่าง "เลือกเสียง" ของสตูดิโอ แล้วกด "นำไปใช้")', 'ใช้ไลฟ์/เสียงทดสอบที่ลบทิ้งได้ เพราะยืนยันแล้วเสียงถูกลบถาวร'],
