   pre=['ในเมนู "คำเสี่ยง" มีคำทดสอบระดับ workspace (ใช้ทุกหมวด) 2 คำ: คำ X ที่ "การจัดการ" เป็น Block และคำ Y ที่ "การจัดการ" เป็น Warn', 'มีสคริปต์ฉบับร่างที่ผูกสินค้าแล้ว และบล็อกแรกมี 2 Content ที่ไม่มีคำเสี่ยง'],
