   pre=['มีสคริปต์สถานะรอรีวิวที่ไม่มีคำเสี่ยงและไม่มีเนื้อหาที่ห้ามออกอากาศ', 'บัญชี Owner มีชื่อแสดงในเมนู "ทีมงาน"'],
