   pre=['โปรเจกต์ในเมนู "โปรเจกต์ของฉัน" ที่ฉากมีอวาตาร์และเสียง ผูกสคริปต์ที่อนุมัติแล้ว และยังไม่มีเลเยอร์ข้อความที่มีคำ "AI Generated" หรือ "AI Live"'],
