      'ปิดหน้าต่าง กลับไป "โปรเจกต์ของฉัน" กด "แก้ไขต่อ" ที่โปรเจกต์ B แล้วกดปุ่ม "เริ่มไลฟ์" อ่านข้อ "ตรวจคำเสี่ยง" และดูปุ่ม "ไลฟ์เลย"',
