   pre=['ล็อกอินด้วย Owner ของ WS-A ได้', 'ให้ dev ปิดฟีเจอร์ AI ตอบคอมเมนต์ทั้งระบบบน UAT ชั่วคราว (ประสานก่อนทดสอบ)', 'WS-A มีรอบไลฟ์ "QA-E13 Live" ที่ยืนยันแล้วแต่ยังไม่ออกอากาศ', 'WS-A มีบัญชี TikTok ที่บันทึกไว้แล้วอย่างน้อย 1 บัญชี', NEW_ROUND],
