      'ที่หัวข้อ "วิธีออกอากาศ" เลือก "ส่งตรงเข้า TikTok (RTMP · ไม่ต้องใช้โทรศัพท์)" เลือกบัญชีทดสอบ กด "เริ่มไลฟ์เข้า TikTok (RTMP)" รอจนสถานะเป็น "กำลังไลฟ์" แล้วกด "เปิดแท็บใหม่" (ข้าง "บังคับปิดไลฟ์")',
