   pre=['ล็อกอินเป็น Owner', 'ให้ dev ช่วยจัดรอบไลฟ์ที่ออกอากาศอยู่แต่ห้อง TikTok ไม่ได้ถูกเปิดโดยระบบ (ระบบไม่มีห้องให้ผูก) บน UAT', 'มีบัญชี TikTok ทดสอบของทีมพร้อมพิมพ์คอมเมนต์'],
