   pre=PRE_ON_AIR[:-1] + ['มีบัญชี TikTok ทดสอบของทีม 3 บัญชีพร้อมพิมพ์คอมเมนต์ และมีผู้เฝ้าไลฟ์ที่กด "บังคับปิดไลฟ์" ได้ทันที'],
