   pre=PRE_ON_AIR[:-1] + ['สคริปต์ของรอบมีบล็อกหนึ่งที่เขียนโปรไว้ (เช่น "วันนี้ซื้อ 2 ตัวแถมฟรี 1 ตัว") และบล็อกอื่นที่ไม่มีโปรเลย', 'มีบัญชี TikTok ทดสอบของทีม 3 บัญชี และมีผู้เฝ้าไลฟ์ที่กด "บังคับปิดไลฟ์" ได้ทันที'],
